-- The table of the decimal compare tests against DOUBLE literals: `tf`, built by the
-- pinned DuckDB. DuckDB compares a DECIMAL column with a DOUBLE in DOUBLE; a
-- stored value past 2^53 is converted by parts (the integer part and the fraction
-- apart), not as one double divided by the power of ten, so these columns hold values
-- on both sides of 2^53 unscaled, at narrow and wide precisions and at scale 0, 2 and 10.

CREATE TABLE tf AS
SELECT * FROM (VALUES
  (1::BIGINT, 90071992547409.93::DECIMAL(18, 2), 90071992547409.93::DECIMAL(19, 2), 123456789012345678901234567890123456.78::DECIMAL(38, 2), 9007199254.7409932000::DECIMAL(38, 10), 9007199254740993::DECIMAL(18, 0), 9007199254740993::DECIMAL(38, 0), 0.30::DECIMAL(15, 2)),
  (2::BIGINT, 90071992547409.92::DECIMAL(18, 2), 92233720368547758.07::DECIMAL(19, 2), 90071992547409.93::DECIMAL(38, 2), 9007199254.7409930000::DECIMAL(38, 10), 9007199254740992::DECIMAL(18, 0), 9007199254740992::DECIMAL(38, 0), 0.01::DECIMAL(15, 2)),
  (3::BIGINT, 90071992547409.94::DECIMAL(18, 2), 0.30::DECIMAL(19, 2), 0.30::DECIMAL(38, 2), 0.3000000000::DECIMAL(38, 10), 9007199254740991::DECIMAL(18, 0), 123456789012345678901234567890123456::DECIMAL(38, 0), 1.00::DECIMAL(15, 2)),
  (4::BIGINT, 0.30::DECIMAL(18, 2), -92233720368547758.07::DECIMAL(19, 2), -90071992547409.93::DECIMAL(38, 2), 0.0000000001::DECIMAL(38, 10), 0::DECIMAL(18, 0), 0::DECIMAL(38, 0), 0.29::DECIMAL(15, 2)),
  (5::BIGINT, 0.01::DECIMAL(18, 2), 12345678901234567.89::DECIMAL(19, 2), 1.00::DECIMAL(38, 2), -9007199254.7409932000::DECIMAL(38, 10), 1::DECIMAL(18, 0), 1::DECIMAL(38, 0), 0.31::DECIMAL(15, 2)),
  (6::BIGINT, -90071992547409.93::DECIMAL(18, 2), 0.01::DECIMAL(19, 2), 99999999999999999999999999999999999.99::DECIMAL(38, 2), 12345678901234567890123456.7890123456::DECIMAL(38, 10), -9007199254740993::DECIMAL(18, 0), -9007199254740993::DECIMAL(38, 0), 9999999999999.99::DECIMAL(15, 2)),
  (7::BIGINT, 9999999999999999.99::DECIMAL(18, 2), 90071992547409.94::DECIMAL(19, 2), 0.01::DECIMAL(38, 2), 1.0000000000::DECIMAL(38, 10), 999999999999999999::DECIMAL(18, 0), 99999999999999999999999999999999999999::DECIMAL(38, 0), -0.30::DECIMAL(15, 2)),
  (8::BIGINT, 450359962737049.65::DECIMAL(18, 2), 1.00::DECIMAL(19, 2), 90071992547409.92::DECIMAL(38, 2), 9007199254.7409940000::DECIMAL(38, 10), 4503599627370497::DECIMAL(18, 0), 18014398509481985::DECIMAL(38, 0), 90071992547.41::DECIMAL(15, 2)),
  (9::BIGINT, NULL::DECIMAL(18, 2), NULL::DECIMAL(19, 2), NULL::DECIMAL(38, 2), NULL::DECIMAL(38, 10), NULL::DECIMAL(18, 0), NULL::DECIMAL(38, 0), NULL::DECIMAL(15, 2))
) AS e(id, fb, fc, fd, fe, ff, fg, fh);
